"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[2548],{66758:e=>{e.exports=JSON.parse('{"functions":[{"name":"addValue","desc":"Adds a delta to the player\'s value on the named leaderboard.\\n\\nAsserts that the leaderboard exists in `LeaderboardData.data`; warns and\\nno-ops if the matching OrderedDB instance has not been connected yet (i.e.\\n[LeaderboardService.init] has not run, or ran with the feature flag off).","params":[{"name":"leaderboardName","desc":"key in `LeaderboardData.data`","lua_type":"string"},{"name":"player","desc":"player whose entry to bump","lua_type":"Player"},{"name":"valueToAdd","desc":"delta to add","lua_type":"number"}],"returns":[],"function_type":"static","source":{"line":105,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"setValue","desc":"Overwrites the player\'s value on the named leaderboard.\\n\\nBy default OrderedDB only accepts a value that beats the stored one; pass\\n`forceSet` to write it unconditionally. After the write, a debounced\\n`LOCAL_UPDATE_DELAY` (30s) task replays every leaderboard value back to that\\nclient \u2014 repeated calls cancel and reschedule the pending push, so a burst\\nof updates results in a single replication.","params":[{"name":"leaderboardName","desc":"key in `LeaderboardData.data`","lua_type":"string"},{"name":"player","desc":"player whose entry to write","lua_type":"Player"},{"name":"newValue","desc":"value to store","lua_type":"number"},{"name":"forceSet","desc":"write even when it does not beat the stored value","lua_type":"boolean?"}],"returns":[],"function_type":"static","source":{"line":144,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_connectDatastores","desc":"Iterates LeaderboardData and connects an OrderedDB class to the service\\nmatching the name in the static data. Populates `_instance`, keyed by\\nleaderboard name.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":203,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_beginCache","desc":"Only runs in the lobby. Keeps a cache of all of the top global leaderboard\\ncategories.\\n\\nPrimes the player-scoped and friends caches for everyone already present,\\nrepeats that for each join, and tears both caches (plus any pending\\nreplication thread) down on leave.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":221,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_cacheUsernames","desc":"Batch-resolves user ids into `usernameCache` via\\n`UserService:GetUserInfosByUserIdsAsync`. The call is throttled by Roblox\\nand is wrapped in a pcall \u2014 on failure the ids are simply left uncached and\\nrender as `[ CONTENT DELETED ]`.","params":[{"name":"userNames","desc":"user ids to resolve","lua_type":"{ number }"}],"returns":[],"function_type":"static","private":true,"source":{"line":264,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_cacheGlobalData","desc":"Refreshes the cache of global top scores and broadcasts each leaderboard to\\nevery client.\\n\\nFor each leaderboard it reads the top `GLOBAL_COUNT_TO_DISPLAY` rows,\\npre-resolves any missing usernames first, and only then overwrites\\n`globalCache` \u2014 the top-value read can yield across retries, so overwriting\\nbeforehand would leave the cache empty for the duration.","params":[],"returns":[],"function_type":"static","private":true,"source":{"line":291,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_cachePlayerScopedData","desc":"Loads the leaderboard stats for a single player into `playerCache`. One\\nOrderedDB read per leaderboard, so this yields.","params":[{"name":"player","desc":"player to cache","lua_type":"Player"}],"returns":[],"function_type":"static","private":true,"source":{"line":362,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"_cacheFriendsData","desc":"Loads the leaderboard stats for this player\'s friends and pushes them to\\nthat client, one leaderboard at a time.\\n\\nThe friend id list is resolved once per session and memoised in\\n`friendsIdCache`; only friends recorded in `HasPlayedDB` are kept, and the\\nplayer themself is appended so they can see where they place. A failed\\n`GetFriendsAsync` retries by recursing, guarded on the player still being\\nin-game. `friendsCacheDebounce` prevents concurrent refreshes for the same\\nplayer, and every loop re-checks that the player has not left mid-yield.\\n\\nUnder `GameData.isLocalFile` the friends API is unavailable, so this seeds\\nan empty id cache and returns.","params":[{"name":"player","desc":"player whose friends to cache","lua_type":"Player"}],"returns":[],"function_type":"static","private":true,"source":{"line":397,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}},{"name":"init","desc":"Boots the service and connects data caching.\\n\\nWhen `FeatureFlags.Leaderboards` is **off** this does the opposite of a\\nno-op: it destroys every instance tagged `LeaderboardData.DISPLAY_PART_TAG`\\n(the whole model when the tagged part is its PrimaryPart, otherwise just the\\npart), stays subscribed so any later-added tagged instance is destroyed too,\\nand returns without touching the datastores.\\n\\nWith the flag on it connects the OrderedDB instances, primes the per-player\\nand friends caches, kicks off the `REFRESH_RATE` global/friends refresh\\nloop, binds `LeaderboardData.remote` for `ClientLoaded` and `GetFriends`\\nrequests, records every player into `HasPlayedDB`, and flushes tracked\\nvalues into the leaderboards when a player leaves.","params":[],"returns":[],"function_type":"static","source":{"line":537,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}}],"properties":[],"types":[],"name":"LeaderboardService","desc":"Saves player statistic data to ordered datastores in round places, and\\ndisplays that data on surface GUIs in the lobby. Displays support filtering\\nby global and friends.\\n\\nAuthor: Zach Curtis (InfinityDesign)\\n\\nOne [OrderedDB] instance is created per entry in\\n`Shared.Data.Social.LeaderboardData.data`, keyed by leaderboard name. Three\\ncaches sit in front of those stores and are pushed to clients over\\n`LeaderboardData.remote`:\\n\\n- `globalCache` \u2014 the top `GLOBAL_COUNT_TO_DISPLAY` (10) entries per\\n  leaderboard, refreshed every `REFRESH_RATE` (60s) and broadcast to all\\n  clients.\\n- `playerCache` \u2014 the calling player\'s own value per leaderboard, filled on\\n  join.\\n- `friendsCache` \u2014 per-player, per-leaderboard values for every friend that\\n  has played before (gated on `HasPlayedDB`), unsorted; the client sorts.\\n\\n`usernameCache` fronts `UserService:GetUserInfosByUserIdsAsync`, which is\\nthrottled, and banned/unresolvable users render as `[ CONTENT DELETED ]`.\\n\\n:::caution Inverted feature gate\\n`FeatureFlags.Leaderboards` is currently **on**. Unlike most gated systems,\\nthe OFF branch is not a no-op: when the flag is off [LeaderboardService.init]\\nactively **destroys** every instance tagged\\n`LeaderboardData.DISPLAY_PART_TAG` in the place \u2014 and keeps destroying newly\\nadded ones via `GetInstanceAddedSignal` \u2014 before returning early. Turning\\nthe flag off therefore removes the leaderboard models from the running\\nplace rather than just leaving them unpopulated.\\n:::\\n\\nCopyright (c) 2026 firebit. All rights reserved.\\nfirebit/murder-escape - proprietary and confidential.","realm":["Server"],"source":{"line":40,"path":"src/Server/Features/Core/Leaderboards/LeaderboardService.luau"}}')}}]);